INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('ru','ManageIPRView','note_task_mode_publish','Задачи Bitrix24 создаются только после публикации ИПР. На последнем шаге нажмите «Сохранить и опубликовать».');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('en','ManageIPRView','note_task_mode_publish','Bitrix24 tasks are created only after the IDP is published. On the final step, click Save and publish.');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('ua','ManageIPRView','note_task_mode_publish','Задачі Bitrix24 створюються лише після публікації ІПР. На останньому кроці натисніть «Зберегти та опублікувати».');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('fr','ManageIPRView','note_task_mode_publish','Les tâches Bitrix24 ne sont créées qu\'après publication du PDI. À la dernière étape, cliquez sur Enregistrer et publier.');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('it','ManageIPRView','note_task_mode_publish','Le attività Bitrix24 vengono create solo dopo la pubblicazione del PSI. All\'ultimo passaggio, clicca Salva e pubblica.');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('de','ManageIPRView','note_task_mode_publish','Bitrix24-Aufgaben werden erst nach Veröffentlichung des IEP erstellt. Im letzten Schritt «Speichern und veröffentlichen» wählen.');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('tr','ManageIPRView','note_task_mode_publish','Bitrix24 görevleri yalnızca BGP yayımlandıktan sonra oluşturulur. Son adımda «Kaydet ve yayımla» düğmesine basın.');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('pl','ManageIPRView','note_task_mode_publish','Zadania Bitrix24 powstają dopiero po publikacji IPR. W ostatnim kroku kliknij «Zapisz i opublikuj».');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('pt','ManageIPRView','note_task_mode_publish','As tarefas Bitrix24 são criadas somente após publicar o PDI. Na etapa final, clique em Salvar e publicar.');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('es','ManageIPRView','note_task_mode_publish','Las tareas Bitrix24 se crean solo tras publicar el PDI. En el último paso, pulse Guardar y publicar.');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('vn','ManageIPRView','note_task_mode_publish','Nhiệm vụ Bitrix24 chỉ được tạo sau khi xuất bản KHPT. Ở bước cuối, nhấn Lưu và xuất bản.');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('zh','ManageIPRView','note_task_mode_publish','Bitrix24 任务仅在发布个人发展计划后创建。在最后一步请点击“保存并发布”。');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('ja','ManageIPRView','note_task_mode_publish','Bitrix24タスクは計画公開後にのみ作成されます。最終ステップで「保存して公開」を押してください。');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('kz','ManageIPRView','note_task_mode_publish','Bitrix24 тапсырмалары ЖДЖ жарияланғаннан кейін ғана құрылады. Соңғы қадамда «Сақтау және жариялау» батырмасын басыңыз.');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('ar','ManageIPRView','note_task_mode_publish','تُنشأ مهام Bitrix24 فقط بعد نشر الخطة. في الخطوة الأخيرة اضغط «حفظ ونشر».');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('id','ManageIPRView','note_task_mode_publish','Tugas Bitrix24 dibuat hanya setelah rencana dipublikasikan. Di langkah terakhir klik Simpan dan publikasikan.');
INSERT IGNORE INTO `dictionary3` (LANG, COMPONENT, `KEY`, TEXT) VALUES ('ms','ManageIPRView','note_task_mode_publish','Tugasan Bitrix24 dicipta hanya selepas pelan diterbitkan. Pada langkah terakhir klik Simpan dan terbitkan.');
